#!/usr/bin/env bash
set -euo pipefail
ROOT="${ROOT:-/teams/ius_1663576043/hby/rl/ov2}"; PYTHON="${PYTHON:-/root/miniconda3/envs/myconda/bin/python}"; MODE="${MODE:-smoke}"; TS="${TS:-$(date +%Y%m%d_%H%M%S)}"
cd "${ROOT}"; source "${ROOT}/experiments/repro_env.sh" 2>/dev/null || true
export PYTHONPATH="${ROOT}/experiments:${ROOT}/JaxMARL:${PYTHONPATH:-}" XLA_PYTHON_CLIENT_PREALLOCATE="${XLA_PYTHON_CLIENT_PREALLOCATE:-false}" PYTHONUNBUFFERED=1
LAYOUT="${LAYOUT:-counter_circuit}"; SEED="${SEED:-42}"; WANDB_ENTITY="${WANDB_ENTITY:-huiby_tsinghua23}"; WANDB_PROJECT="${WANDB_PROJECT:-ov2-paper-repro}"
if [ "${MODE}" = smoke ]; then NUM_SEEDS="${NUM_SEEDS:-1}"; TOTAL_TIMESTEPS="${TOTAL_TIMESTEPS:-262144}"; REW_SHAPING_HORIZON="${REW_SHAPING_HORIZON:-131072}"; NUM_ITERATIONS="${NUM_ITERATIONS:-1}"; EVAL_SEEDS="${EVAL_SEEDS:-4}"; EVAL_BATCHES="${EVAL_BATCHES:-1}"; WANDB_MODE="${WANDB_MODE:-disabled}"; else NUM_SEEDS="${NUM_SEEDS:-10}"; TOTAL_TIMESTEPS="${TOTAL_TIMESTEPS:-10000000}"; REW_SHAPING_HORIZON="${REW_SHAPING_HORIZON:-5000000}"; NUM_ITERATIONS="${NUM_ITERATIONS:-10}"; EVAL_SEEDS="${EVAL_SEEDS:-500}"; EVAL_BATCHES="${EVAL_BATCHES:-10}"; WANDB_MODE="${WANDB_MODE:-online}"; fi
NUM_ENVS="${NUM_ENVS:-64}"; NUM_STEPS="${NUM_STEPS:-256}"; UPDATE_EPOCHS="${UPDATE_EPOCHS:-4}"; NUM_MINIBATCHES="${NUM_MINIBATCHES:-16}"
POPULATION_SIZE="${POPULATION_SIZE:-5}"; MEP_ENT_COEF="${MEP_ENT_COEF:-0.05}"; MEP_GROUP_MM="${MEP_GROUP_MM:-1}"; MEP_GROUP_MP="${MEP_GROUP_MP:-1}"
TTAC_ADAPTER_SCALE="${TTAC_ADAPTER_SCALE:-0.5}"; TTAC_AGREEMENT_COEF="${TTAC_AGREEMENT_COEF:-0.05}"; TTAC_TRAIN_KL_COEF="${TTAC_TRAIN_KL_COEF:-0.005}"; TTAC_TEST_HIST_KL_COEF="${TTAC_TEST_HIST_KL_COEF:-0.0}"; TTAC_TEST_EGO_KL_COEF="${TTAC_TEST_EGO_KL_COEF:-0.01}"; TTAC_TEST_CUR_KL_COEF="${TTAC_TEST_CUR_KL_COEF:-0.01}"; TTAC_TEST_UPDATE_STEPS="${TTAC_TEST_UPDATE_STEPS:-3}"; TTAC_TEST_LR="${TTAC_TEST_LR:-0.003}"; TTAC_HISTORY_LEN="${TTAC_HISTORY_LEN:-50}"; TTAC_ONLINE_EVAL_PAIRINGS_PER_CHUNK="${TTAC_ONLINE_EVAL_PAIRINGS_PER_CHUNK:-9}"
PREFIX="${PREFIX:-ttac_v2_sync_mep_population_state_aug_64_16_10M_seed42_10seeds_${TS}}"; REPORT_DIR="reports/ttac_v2_sync_population_${TS}"; mkdir -p "${REPORT_DIR}"
echo "[$(date +%F' '%T)] TTACv2 sync population mode=${MODE} prefix=${PREFIX}"
"${PYTHON}" -m overcooked_v2_experiments.ttac_v2.sync_population_main +experiment=cnn +env=original env.ENV_KWARGS.layout="${LAYOUT}" SEED="${SEED}" NUM_SEEDS="${NUM_SEEDS}" NUM_CHECKPOINTS=3 +NUM_ITERATIONS="${NUM_ITERATIONS}" VISUALIZE=False +OPTIONAL_PREFIX="${PREFIX}" wandb.ENTITY="${WANDB_ENTITY}" wandb.PROJECT="${WANDB_PROJECT}" wandb.WANDB_MODE="${WANDB_MODE}" model.TOTAL_TIMESTEPS="${TOTAL_TIMESTEPS}" model.REW_SHAPING_HORIZON="${REW_SHAPING_HORIZON}" model.NUM_ENVS="${NUM_ENVS}" model.NUM_STEPS="${NUM_STEPS}" model.UPDATE_EPOCHS="${UPDATE_EPOCHS}" model.NUM_MINIBATCHES="${NUM_MINIBATCHES}" model.TTAC_ADAPTER_SCALE="${TTAC_ADAPTER_SCALE}" model.TTAC_AGREEMENT_COEF="${TTAC_AGREEMENT_COEF}" model.TTAC_TRAIN_KL_COEF="${TTAC_TRAIN_KL_COEF}" +MEP.POPULATION_SIZE="${POPULATION_SIZE}" +MEP.ENT_COEF="${MEP_ENT_COEF}" +MEP.GROUP_MM="${MEP_GROUP_MM}" +MEP.GROUP_MP="${MEP_GROUP_MP}"
RUN_DIR="$(find "runs/${PREFIX}" -mindepth 1 -maxdepth 1 -type d | sort | tail -n 1)"; echo "${RUN_DIR}" > "${REPORT_DIR}/run_dir.txt"
for mode in base_no_test_adapt ttac_true_history ttac_wrong_history ttac_adapter_off; do
  echo "[$(date +%F' '%T)] Eval ${mode} SP"
  "${PYTHON}" -m overcooked_v2_experiments.ttac_v2.utils.visualize_ppo --d "${RUN_DIR}" --num_seeds "${EVAL_SEEDS}" --no_viz --seed "${SEED}" --ttac_mode "${mode}" --output_tag "${mode}" --eval_batches "${EVAL_BATCHES}"     --ttac_adapter_scale "${TTAC_ADAPTER_SCALE}" --ttac_test_hist_kl_coef "${TTAC_TEST_HIST_KL_COEF}" --ttac_test_ego_kl_coef "${TTAC_TEST_EGO_KL_COEF}" --ttac_test_cur_kl_coef "${TTAC_TEST_CUR_KL_COEF}" --ttac_test_lr "${TTAC_TEST_LR}" --ttac_test_update_steps "${TTAC_TEST_UPDATE_STEPS}" --ttac_history_len "${TTAC_HISTORY_LEN}" --online_eval_pairings_per_chunk "${TTAC_ONLINE_EVAL_PAIRINGS_PER_CHUNK:-9}"
  echo "[$(date +%F' '%T)] Eval ${mode} cross"
  "${PYTHON}" -m overcooked_v2_experiments.ttac_v2.utils.visualize_ppo --d "${RUN_DIR}" --cross --num_seeds "${EVAL_SEEDS}" --no_viz --seed "${SEED}" --ttac_mode "${mode}" --output_tag "${mode}" --eval_batches "${EVAL_BATCHES}"     --ttac_adapter_scale "${TTAC_ADAPTER_SCALE}" --ttac_test_hist_kl_coef "${TTAC_TEST_HIST_KL_COEF}" --ttac_test_ego_kl_coef "${TTAC_TEST_EGO_KL_COEF}" --ttac_test_cur_kl_coef "${TTAC_TEST_CUR_KL_COEF}" --ttac_test_lr "${TTAC_TEST_LR}" --ttac_test_update_steps "${TTAC_TEST_UPDATE_STEPS}" --ttac_history_len "${TTAC_HISTORY_LEN}" --online_eval_pairings_per_chunk "${TTAC_ONLINE_EVAL_PAIRINGS_PER_CHUNK:-9}"
done

